{"script":"() => { 
  // Try to find and dismiss any modal/overlay
  const overlays = document.querySelectorAll('[role="dialog"], [aria-modal="true"]');
  if (overlays.length > 0) {
    return { found: true, count: overlays.length, classes: Array.from(overlays).map(o => o.className.substring(0, 100)) };
  }
  // Try to close by sending Escape key
  return { found: false };
}"}

